class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        m, n = len(board), len(board[0])
        DIR = [0, 1, 0, -1, 0]
        found = False
        seen = set()
        path = []

        def dfs(r: int, c: int) -> None:
            nonlocal found
            if path and len(path) < len(word) and word[len(path)] != board[r][c]:
                return

            path.append(board[r][c])
            seen.add((r, c))

            if len(path) == len(word):
                found = True
                return

            for i in range(4):
                nr, nc = r + DIR[i], c + DIR[i + 1]
                if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in seen:
                    dfs(nr, nc)

            path.pop()
            seen.remove((r,c))

        for i in range(m):
            for j in range(n):
                if board[i][j] == word[0]:
                    dfs(i, j)

        return found
